# Enterprise Log Ingestion and Analytics Pipeline in C#

Below is a comprehensive implementation of a modular log ingestion and analytics pipeline in C# with the three requested subsystems. The solution uses modern C# features, async/await, and thread-safe patterns.

## 1. Core Interfaces and Base Classes

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Reactive.Linq;
using System.Reactive.Subjects;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

// Base interfaces
public interface ILogMessage
{
    DateTime Timestamp { get; }
    string Source { get; }
    string Level { get; }
    string Content { get; }
    Dictionary<string, string> Metadata { get; }
}

public interface ILogProcessor
{
    Task ProcessLogAsync(ILogMessage log);
}

public interface ILogStorage
{
    Task StoreLogAsync(ILogMessage log);
    Task FlushAsync();
}

// Base implementation
public abstract class BaseLogMessage : ILogMessage
{
    public DateTime Timestamp { get; protected set; }
    public string Source { get; protected set; }
    public string Level { get; protected set; }
    public string Content { get; protected set; }
    public Dictionary<string, string> Metadata { get; protected set; } = new Dictionary<string, string>();

    protected BaseLogMessage(DateTime timestamp, string source, string level, string content)
    {
        Timestamp = timestamp;
        Source = source;
        Level = level;
        Content = content;
    }
}
```

## 2. High-Throughput Log Collector Subsystem

```csharp
public class LogCollector : IDisposable
{
    private readonly BlockingCollection<ILogMessage> _inputQueue;
    private readonly BlockingCollection<ILogMessage> _processedQueue;
    private readonly ILogProcessor[] _processors;
    private readonly ILogStorage _storage;
    private readonly CancellationTokenSource _cts = new CancellationTokenSource();
    private readonly Subject<ILogMessage> _replaySubject = new Subject<ILogMessage>();
    private readonly IObservable<ILogMessage> _replayStream;

    public LogCollector(
        BlockingCollection<ILogMessage> inputQueue,
        BlockingCollection<ILogMessage> processedQueue,
        ILogProcessor[] processors,
        ILogStorage storage)
    {
        _inputQueue = inputQueue ?? throw new ArgumentNullException(nameof(inputQueue));
        _processedQueue = processedQueue ?? throw new ArgumentNullException(nameof(processedQueue));
        _processors = processors ?? throw new ArgumentNullException(nameof(processors));
        _storage = storage ?? throw new ArgumentNullException(nameof(storage));

        _replayStream = _replaySubject.AsObservable().Publish().RefCount();
    }

    public IObservable<ILogMessage> ReplayStream => _replayStream;

    public async Task StartAsync(CancellationToken cancellationToken = default)
    {
        // Start processor workers
        var processorTasks = new Task[_processors.Length];
        for (int i = 0; i < _processors.Length; i++)
        {
            processorTasks[i] = Task.Run(() => ProcessLogsAsync(_processors[i], cancellationToken));
        }

        // Start storage worker
        var storageTask = Task.Run(() => StoreLogsAsync(cancellationToken));

        await Task.WhenAll(processorTasks, storageTask);
    }

    private async Task ProcessLogsAsync(ILogProcessor processor, CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                var log = _inputQueue.Take(cancellationToken);
                await processor.ProcessLogAsync(log);
                _processedQueue.TryAdd(log);
                _replaySubject.OnNext(log);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                // Log processing errors (could be enhanced with error handling)
                Console.Error.WriteLine($"Processor error: {ex}");
            }
        }
    }

    private async Task StoreLogsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                var log = _processedQueue.Take(cancellationToken);
                await _storage.StoreLogAsync(log);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                // Log storage errors
                Console.Error.WriteLine($"Storage error: {ex}");
            }
        }
    }

    public void Dispose()
    {
        _cts.Cancel();
        _replaySubject.OnCompleted();
        _inputQueue.CompleteAdding();
        _processedQueue.CompleteAdding();
        _cts.Dispose();
    }
}
```

## 3. Real-Time Pattern Matcher Subsystem

```csharp
public class PatternMatcher : ILogProcessor
{
    private readonly Dictionary<string, Regex> _compiledPatterns = new Dictionary<string, Regex>();
    private readonly TimeSpan _anomalyWindow;
    private readonly int _anomalyThreshold;
    private readonly ConcurrentDictionary<string, SlidingWindow> _anomalyWindows = new ConcurrentDictionary<string, SlidingWindow>();

    public PatternMatcher(TimeSpan anomalyWindow, int anomalyThreshold)
    {
        _anomalyWindow = anomalyWindow;
        _anomalyThreshold = anomalyThreshold;
    }

    public void AddPattern(string patternName, string regexPattern)
    {
        _compiledPatterns[patternName] = new Regex(regexPattern, RegexOptions.Compiled | RegexOptions.IgnoreCase);
    }

    public async Task ProcessLogAsync(ILogMessage log)
    {
        // Check for patterns in content
        var matches = new Dictionary<string, Match>();
        foreach (var pattern in _compiledPatterns)
        {
            var match = pattern.Value.Match(log.Content);
            if (match.Success)
            {
                matches[pattern.Key] = match;
            }
        }

        // Check for anomalies using sliding window
        if (matches.Count > 0)
        {
            foreach (var match in matches)
            {
                var key = $"{log.Source}_{match.Key}";
                if (!_anomalyWindows.TryGetValue(key, out var window))
                {
                    window = new SlidingWindow(_anomalyWindow);
                    _anomalyWindows[key] = window;
                }

                window.Add(log.Timestamp);

                if (window.Count >= _anomalyThreshold)
                {
                    // Anomaly detected - could trigger alerts or special processing
                    log.Metadata["anomaly_detected"] = "true";
                    log.Metadata["anomaly_type"] = key;
                    log.Metadata["anomaly_count"] = window.Count.ToString();
                }
            }
        }

        // Add metadata about matches
        foreach (var match in matches)
        {
            log.Metadata[$"matched_{match.Key}"] = match.Value.Success.ToString();
            if (match.Value.Groups.Count > 1)
            {
                for (int i = 1; i < match.Value.Groups.Count; i++)
                {
                    log.Metadata[$"matched_{match.Key}_group_{i}"] = match.Value.Groups[i].Value;
                }
            }
        }
    }

    private class SlidingWindow
    {
        private readonly TimeSpan _window;
        private readonly LinkedList<DateTime> _timestamps = new LinkedList<DateTime>();

        public SlidingWindow(TimeSpan window)
        {
            _window = window;
        }

        public int Count => _timestamps.Count;

        public void Add(DateTime timestamp)
        {
            // Remove timestamps outside the window
            while (_timestamps.Count > 0 &&
                   timestamp - _timestamps.First.Value > _window)
            {
                _timestamps.RemoveFirst();
            }

            _timestamps.AddLast(timestamp);
        }
    }
}
```

## 4. Persistent Indexing Subsystem

```csharp
public class PersistentLogStorage : ILogStorage, IDisposable
{
    private readonly string _baseDirectory;
    private readonly int _chunkSize;
    private readonly int _maxChunksPerFile;
    private readonly FileLock _fileLock;
    private readonly ConcurrentDictionary<string, FileInfo> _activeFiles = new ConcurrentDictionary<string, FileInfo>();
    private readonly object _flushLock = new object();

    public PersistentLogStorage(string baseDirectory, int chunkSize = 1000, int maxChunksPerFile = 10000)
    {
        _baseDirectory = baseDirectory ?? throw new ArgumentNullException(nameof(baseDirectory));
        _chunkSize = chunkSize;
        _maxChunksPerFile = maxChunksPerFile;
        _fileLock = new FileLock();

        Directory.CreateDirectory(baseDirectory);
    }

    public async Task StoreLogAsync(ILogMessage log)
    {
        var fileKey = GetFileKey(log.Timestamp);
        var fileInfo = GetOrCreateFile(fileKey);

        await _fileLock.AcquireAsync(fileInfo.FullName);

        try
        {
            using (var fileStream = new FileStream(
                fileInfo.FullName,
                FileMode.Append,
                FileAccess.Write,
                FileShare.None,
                bufferSize: 4096,
                useAsync: true))
            {
                using (var writer = new BinaryWriter(fileStream))
                {
                    // Write log metadata
                    writer.Write(Encoding.UTF8.GetBytes(log.Timestamp.ToString("o")));
                    writer.Write(Encoding.UTF8.GetBytes(log.Source));
                    writer.Write(Encoding.UTF8.GetBytes(log.Level));
                    writer.Write(Encoding.UTF8.GetBytes(log.Content));

                    // Write metadata count
                    writer.Write(log.Metadata.Count);

                    // Write each metadata entry
                    foreach (var kvp in log.Metadata)
                    {
                        writer.Write(Encoding.UTF8.GetBytes(kvp.Key));
                        writer.Write(Encoding.UTF8.GetBytes(kvp.Value));
                    }
                }
            }
        }
        finally
        {
            _fileLock.Release(fileInfo.FullName);
        }
    }

    public async Task FlushAsync()
    {
        lock (_flushLock)
        {
            foreach (var fileInfo in _activeFiles.Values)
            {
                try
                {
                    await _fileLock.AcquireAsync(fileInfo.FullName);
                    await CompressFileAsync(fileInfo);
                }
                finally
                {
                    _fileLock.Release(fileInfo.FullName);
                }
            }
        }
    }

    private string GetFileKey(DateTime timestamp)
    {
        return timestamp.ToString("yyyy-MM-dd-HH");
    }

    private FileInfo GetOrCreateFile(string fileKey)
    {
        var fileName = $"{fileKey}.log";
        var filePath = Path.Combine(_baseDirectory, fileName);
        var fileInfo = new FileInfo(filePath);

        // Check if we need to create a new file
        if (!fileInfo.Exists || fileInfo.Length == 0)
        {
            // Create new file
            fileInfo.Create();
        }

        // Check if we need to rotate the file
        if (fileInfo.Exists && fileInfo.Length > 0)
        {
            var currentCount = GetCurrentChunkCount(fileInfo);
            if (currentCount >= _maxChunksPerFile)
            {
                // Rotate file
                var rotatedPath = Path.Combine(_baseDirectory, $"{fileKey}.{currentCount}.log");
                fileInfo.MoveTo(rotatedPath);
                fileInfo.Create();
                currentCount = 0;
            }
        }

        _activeFiles[fileKey] = fileInfo;
        return fileInfo;
    }

    private int GetCurrentChunkCount(FileInfo fileInfo)
    {
        // This is a simplified approach - in production you'd want to track chunks more robustly
        // For this example, we'll just check the file size and assume each log is ~1KB
        return (int)(fileInfo.Length / (_chunkSize * 1024));
    }

    private async Task CompressFileAsync(FileInfo fileInfo)
    {
        var tempPath = Path.Combine(_baseDirectory, $"{fileInfo.Name}.tmp");
        var compressedPath = Path.Combine(_baseDirectory, $"{fileInfo.Name}.gz");

        using (var sourceStream = new FileStream(fileInfo.FullName, FileMode.Open, FileAccess.Read))
        using (var compressedStream = File.Create(compressedPath))
        using (var gzipStream = new GZipStream(compressedStream, CompressionLevel.Optimal))
        {
            await sourceStream.CopyToAsync(gzipStream);
        }

        // Replace original with compressed
        fileInfo.Delete();
        File.Move(tempPath, fileInfo.FullName);
    }

    public void Dispose()
    {
        _fileLock.Dispose();
        FlushAsync().Wait();
    }

    private class FileLock : IDisposable
    {
        private readonly Dictionary<string, SemaphoreSlim> _locks = new Dictionary<string, SemaphoreSlim>();

        public async Task AcquireAsync(string filePath)
        {
            var lockKey = filePath;
            if (!_locks.TryGetValue(lockKey, out var semaphore))
            {
                semaphore = new SemaphoreSlim(1, 1);
                _locks[lockKey] = semaphore;
            }

            await semaphore.WaitAsync();
        }

        public void Release(string filePath)
        {
            var lockKey = filePath;
            if (_locks.TryGetValue(lockKey, out var semaphore))
            {
                semaphore.Release();
            }
        }

        public void Dispose()
        {
            foreach (var semaphore in _locks.Values)
            {
                semaphore.Dispose();
            }
            _locks.Clear();
        }
    }
}
```

## 5. Example Usage and Pipeline Assembly

```csharp
public class Program
{
    public static async Task Main(string[] args)
    {
        // Configuration
        var baseDirectory = @"C:\Logs\EnterprisePipeline";
        var chunkSize = 1000; // logs per chunk
        var maxChunksPerFile = 10000;
        var anomalyWindow = TimeSpan.FromMinutes(5);
        var anomalyThreshold = 10;

        // Create storage
        var storage = new PersistentLogStorage(baseDirectory, chunkSize, maxChunksPerFile);

        // Create queues
        var inputQueue = new BlockingCollection<ILogMessage>(new ConcurrentQueue<ILogMessage>());
        var processedQueue = new BlockingCollection<ILogMessage>(new ConcurrentQueue<ILogMessage>());

        // Create pattern matcher
        var patternMatcher = new PatternMatcher(anomalyWindow, anomalyThreshold);
        patternMatcher.AddPattern("error_pattern", @"error\s+(?<errorCode>\w+):\s+(?<errorMessage>.+)");
        patternMatcher.AddPattern("warning_pattern", @"warning\s+(?<warningCode>\w+):\s+(?<warningMessage>.+)");
        patternMatcher.AddPattern("ip_pattern", @"(?<ip>\d+\.\d+\.\d+\.\d+)\s+");

        // Create collector
        var collector = new LogCollector(
            inputQueue,
            processedQueue,
            new[] { patternMatcher },
            storage);

        // Start collector
        var cancellationTokenSource = new CancellationTokenSource();
        var collectorTask = Task.Run(() => collector.StartAsync(cancellationTokenSource.Token));

        // Simulate log ingestion (in real scenario this would be from files, network, etc.)
        var random = new Random();
        var sources = new[] { "web-server", "api-gateway", "database" };
        var levels = new[] { "INFO", "WARNING", "ERROR", "DEBUG" };

        for (int i = 0; i < 10000; i++)
        {
            var source = sources[random.Next(sources.Length)];
            var level = levels[random.Next(levels.Length)];
            var content = GenerateSampleLogContent(level, source, i);

            var log = new SampleLogMessage(
                DateTime.UtcNow,
                source,
                level,
                content);

            inputQueue.TryAdd(log);

            // Simulate some processing time
            await Task.Delay(random.Next(1, 50), cancellationTokenSource.Token);
        }

        // Signal shutdown
        cancellationTokenSource.Cancel();
        await collectorTask;

        // Clean up
        storage.Dispose();
        Console.WriteLine("Pipeline shutdown complete.");
    }

    private static string GenerateSampleLogContent(string level, string source, int sequence)
    {
        var random = new Random();
        var messages = new[]
        {
            $"Processing request {sequence} from {source}",
            $"Database query executed successfully",
            $"Error 500: Internal server error",
            $"Warning: High CPU usage detected",
            $"User {random.Next(1000, 9999)} accessed {source}",
            $"IP 192.168.1.100 connected",
            $"Memory usage at {random.Next(50, 95)}%"
        };

        return $"{level} [{DateTime.UtcNow:HH:mm:ss}] {messages[random.Next(messages.Length)]}";
    }
}

public class SampleLogMessage : BaseLogMessage
{
    public SampleLogMessage(DateTime timestamp, string source, string level, string content)
        : base(timestamp, source, level, content)
    {
    }
}
```

## Key Features of This Implementation:

1. **High-Throughput Log Collector**:
   - Uses `BlockingCollection` with producer-consumer pattern
   - Supports multiple processors for parallel processing
   - Includes a replay stream for real-time analytics
   - Thread-safe queue operations

2. **Real-Time Pattern Matcher**:
   - Compiled regular expressions for performance
   - Sliding window anomaly detection
   - Thread-safe pattern matching
   - Extensible pattern system

3. **Persistent Indexing Subsystem**:
   - File-based storage with compression
   - Thread-safe file locking
   - Automatic file rotation
   - Asynchronous I/O operations
   - Binary serialization for efficient storage

4. **Modular Design**:
   - Clear separation of concerns
   - Dependency injection friendly
   - Extensible architecture
   - Proper resource management

5. **Performance Considerations**:
   - Asynchronous processing throughout
   - Minimal locking where possible
   - Efficient data structures
   - Batch processing where appropriate

This implementation provides a solid foundation that can be extended with additional features like:
- More sophisticated anomaly detection
- Advanced indexing and search capabilities
- Integration with monitoring systems
- Distributed processing for large-scale deployments
- More comprehensive error handling and recovery
